-- 001_init.sql
-- The Phylax schema.
--
-- Conventions:
--   * ids are uuid, generated by the database (gen_random_uuid), so nothing has to be coordinated across processes.
--   * times are timestamptz, always stored in UTC; the account's own timezone is a setting, applied when reading.
--   * a shift's start/end are MINUTES AFTER MIDNIGHT and its date is the day it STARTS. An overnight shift (end <=
--     start) is one continuous block that belongs to two calendar days. See shared/shifts.ts.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------------------------------
-- People
-- ---------------------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS accounts (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  display_name    text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 40),
  email           text,
  email_verified  boolean NOT NULL DEFAULT false,
  phone           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

-- One account per address. Case-insensitive, and only for accounts that HAVE an address (a passkey-only account
-- may have none).
CREATE UNIQUE INDEX IF NOT EXISTS accounts_email_lower_uniq ON accounts (lower(email)) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS accounts_phone_idx ON accounts (phone) WHERE phone IS NOT NULL;

-- How a person proves who they are. One row per method they can sign in with.
CREATE TABLE IF NOT EXISTS auth_identities (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id        uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  method            text NOT NULL CHECK (method IN ('password', 'link', 'apple', 'google', 'passkey')),
  -- scrypt hash, for method = 'password'
  password_hash     text,
  -- the credential id from the authenticator, for method = 'passkey'
  credential_id     text,
  -- the provider's own user id, for method = 'apple' | 'google'
  provider_subject  text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  last_used_at      timestamptz
);

-- A passkey belongs to one account and one authenticator, and the same authenticator can never be two accounts.
CREATE UNIQUE INDEX IF NOT EXISTS auth_identities_credential_uniq
  ON auth_identities (credential_id) WHERE credential_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS auth_identities_provider_uniq
  ON auth_identities (method, provider_subject) WHERE provider_subject IS NOT NULL;
-- One identity per method per account, except passkeys: a person may keep several (phone, laptop, tablet).
CREATE UNIQUE INDEX IF NOT EXISTS auth_identities_account_method_uniq
  ON auth_identities (account_id, method) WHERE method <> 'passkey';

-- ---------------------------------------------------------------------------------------------
-- Sessions
-- ---------------------------------------------------------------------------------------------

-- An opaque session id in an httpOnly cookie. The id is random and carries no information; everything else about
-- the session lives here, which is what makes "sign out everywhere" and expiry a database question, not a token one.
CREATE TABLE IF NOT EXISTS sessions (
  id            text PRIMARY KEY,
  account_id    uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_seen_at  timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL,
  user_agent    text,
  ip            inet
);

CREATE INDEX IF NOT EXISTS sessions_account_idx ON sessions (account_id);
CREATE INDEX IF NOT EXISTS sessions_expires_idx ON sessions (expires_at);

-- ---------------------------------------------------------------------------------------------
-- The sign-up in progress
-- ---------------------------------------------------------------------------------------------

-- A sign-in that found no account. The server holds it here and the browser holds only a signed cookie with the
-- id, so the pending sign-up cannot be read or edited from the client, and it expires on its own.
CREATE TABLE IF NOT EXISTS pending_signups (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  method            text NOT NULL CHECK (method IN ('password', 'link', 'apple', 'google', 'passkey')),
  email             text,
  provider          text,
  provider_subject  text,
  display_name      text,
  -- The password typed at sign-in becomes the account's password if the person goes on to create the account.
  password_hash     text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  expires_at        timestamptz NOT NULL
);

CREATE INDEX IF NOT EXISTS pending_signups_expires_idx ON pending_signups (expires_at);

-- One-time sign-in links. Only the hash of the token is stored, so a database leak cannot be replayed.
CREATE TABLE IF NOT EXISTS magic_links (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email       text NOT NULL,
  token_hash  text NOT NULL UNIQUE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  consumed_at timestamptz
);

CREATE INDEX IF NOT EXISTS magic_links_email_idx ON magic_links (email);

-- ---------------------------------------------------------------------------------------------
-- Shifts
-- ---------------------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS shifts (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id   uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  platform     text NOT NULL,
  facility     text NOT NULL,
  label        text NOT NULL DEFAULT '',
  -- minutes after midnight; end <= start means the shift runs overnight
  start_minute integer NOT NULL CHECK (start_minute BETWEEN 0 AND 1439),
  end_minute   integer NOT NULL CHECK (end_minute   BETWEEN 0 AND 1439),
  -- the day the shift starts
  date         date NOT NULL,
  note         text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS shifts_account_date_idx ON shifts (account_id, date);
CREATE INDEX IF NOT EXISTS shifts_account_start_idx ON shifts (account_id, start_minute);

-- The saved tiles: a facility and its hours, without a date.
CREATE TABLE IF NOT EXISTS patterns (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id   uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  facility     text NOT NULL,
  label        text NOT NULL DEFAULT '',
  start_minute integer NOT NULL CHECK (start_minute BETWEEN 0 AND 1439),
  end_minute   integer NOT NULL CHECK (end_minute   BETWEEN 0 AND 1439),
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS patterns_account_idx ON patterns (account_id);

-- ---------------------------------------------------------------------------------------------
-- Per-account settings
-- ---------------------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS account_settings (
  account_id             uuid PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
  -- the travel buffer, in minutes: the gap the person needs between two different facilities
  travel_minutes         integer NOT NULL DEFAULT 60 CHECK (travel_minutes BETWEEN 0 AND 1440),
  -- the assumed cancellation window, in hours
  cancel_hours           integer NOT NULL DEFAULT 24  CHECK (cancel_hours   BETWEEN 0 AND 720),
  -- IANA timezone, used to read "9:42 PM" in the alert the way the person would say it
  timezone               text NOT NULL DEFAULT 'UTC',
  sms_enabled            boolean NOT NULL DEFAULT false,
  email_enabled          boolean NOT NULL DEFAULT false,
  phone                  text,
  -- how long before a cancellation window closes the reminder goes out, in minutes
  reminder_lead_minutes  integer NOT NULL DEFAULT 180 CHECK (reminder_lead_minutes BETWEEN 0 AND 10080),
  updated_at             timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------------------------
-- Reminders
-- ---------------------------------------------------------------------------------------------

-- The queue the scheduler works from. A reminder is created when it is due and marked sent when it goes out.
-- The dedupe key is what makes a reminder exactly-once: a repeated tick, a restarted process or a second instance
-- cannot send the same warning twice.
CREATE TABLE IF NOT EXISTS reminders (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id      uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  shift_id        uuid REFERENCES shifts(id) ON DELETE CASCADE,
  kind            text NOT NULL CHECK (kind IN ('overlap', 'tight', 'cancellation')),
  -- e.g. 'cancel:<shift id>:<window start>' or 'conflict:<shift id>:<other shift id>:<kind>'
  dedupe_key      text NOT NULL UNIQUE,
  scheduled_for   timestamptz NOT NULL,
  sent_at         timestamptz,
  channel         text,
  error           text,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS reminders_due_idx ON reminders (scheduled_for) WHERE sent_at IS NULL;
CREATE INDEX IF NOT EXISTS reminders_account_idx ON reminders (account_id, created_at DESC);
